query.base:
SET unmapped_fields="NULLIFY";
// A cluster that has only ever collected one metric generation has no mapping for the other.
// NULLIFY reads a never-mapped field as null instead of failing the query, so the fallback below
// works whichever generation is collected.
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND (`metrics.storage.googleapis.com/storage/v2/total_count` IS NOT NULL
         OR `metrics.storage.googleapis.com/storage/v2/total_bytes` IS NOT NULL
         OR `metrics.storage.googleapis.com/storage/object_count` IS NOT NULL
         OR `metrics.storage.googleapis.com/storage/total_bytes` IS NOT NULL)
//
// --- Metric generations ------------------------------------------------------------------------
// Cloud Storage publishes object counts and stored bytes twice: storage/v2/total_count and
// storage/v2/total_bytes, split by object type, and the legacy storage/object_count and
// storage/total_bytes, which cover live and noncurrent objects only. Only those two v2 types are
// read, so the result is the same whichever generation is collected and switching from one to the
// other does not look like sprawl. Soft-deleted objects and incomplete multipart uploads are
// excluded. Legacy documents carry no type.
    AND (attributes.type IS NULL OR attributes.type IN ("live-object", "noncurrent-object"))
//
// --- Snapshot handling -------------------------------------------------------------------------
// Both metrics are point-in-time snapshots recomputed roughly once per day and re-reported on every
// poll. They must NEVER be summed over time. Only the 2-day head and tail slices of the window are
// compared; both always contain a daily snapshot.
| WHERE @timestamp >= NOW() - 2 days OR @timestamp < NOW() - 12 days
// Object counts and bytes do not reliably share a document, so each is aggregated independently and
// the ratio is taken afterwards — never with per-document EVAL arithmetic.
// A bucket can hold several storage classes at once. Both metrics and all classes are aligned on the
// same hour before summing, so every bucket total comes from one coherent set of polls: summing
// per-class maxima taken across a whole slice would count data twice if it changed class inside it.
// Within each hour, MAX_OVER_TIME reads each series and MAX collapses the series of one class and
// type: the collector can split a metric across several series (_metric_names_hash is a
// dimension), and those report the same snapshot, so they must never be added together.
| STATS v2_series_objects     = MAX(MAX_OVER_TIME(`metrics.storage.googleapis.com/storage/v2/total_count`)),
        v2_series_bytes       = MAX(MAX_OVER_TIME(`metrics.storage.googleapis.com/storage/v2/total_bytes`)),
        legacy_series_objects = MAX(MAX_OVER_TIME(`metrics.storage.googleapis.com/storage/object_count`)),
        legacy_series_bytes   = MAX(MAX_OVER_TIME(`metrics.storage.googleapis.com/storage/total_bytes`))
    BY resource.attributes.bucket_name, attributes.storage_class, attributes.type, hour = TBUCKET(1 hour)
| EVAL slice = CASE(hour >= NOW() - 2 days, "latest", hour < NOW() - 12 days, "earliest", null)
| WHERE slice IS NOT NULL
| STATS v2_objects     = SUM(v2_series_objects),
        v2_bytes       = SUM(v2_series_bytes),
        legacy_objects = SUM(legacy_series_objects),
        legacy_bytes   = SUM(legacy_series_bytes),
        hour_classes   = VALUES(attributes.storage_class)
    BY resource.attributes.bucket_name, slice, hour
// Use one generation per bucket-hour for both metrics, preferring v2, so the two are never added
// together and the size ratio never mixes them.
| EVAL use_v2 = v2_objects IS NOT NULL AND v2_bytes IS NOT NULL
| EVAL bucket_objects = CASE(use_v2, v2_objects, legacy_objects),
       bucket_bytes   = CASE(use_v2, v2_bytes, legacy_bytes)
// Cast before dividing: object counts are longs and `a / b` would be integer division.
| EVAL bucket_avg_object_bytes = CASE(bucket_objects > 0, bucket_bytes / bucket_objects::DOUBLE, null)
// The median hourly value ignores the odd hour that straddles a class change or misses a poll.
| STATS latest_objects            = MEDIAN(bucket_objects) WHERE slice == "latest",
        earliest_objects          = MEDIAN(bucket_objects) WHERE slice == "earliest",
        latest_bytes              = MEDIAN(bucket_bytes) WHERE slice == "latest",
        earliest_bytes            = MEDIAN(bucket_bytes) WHERE slice == "earliest",
        latest_avg_object_bytes   = MEDIAN(bucket_avg_object_bytes) WHERE slice == "latest",
        earliest_avg_object_bytes = MEDIAN(bucket_avg_object_bytes) WHERE slice == "earliest",
        storage_classes           = VALUES(hour_classes)
    BY resource.attributes.bucket_name

breach.segment:
// Guard every denominator, and ignore buckets too small for operation costs to matter.
// Latest bytes are not a denominator and may be zero: zero-byte objects still cost an operation each.
// 100,000 objects; raise it in estates where small buckets are normal and uninteresting.
WHERE earliest_objects > 0 AND earliest_bytes > 0 AND earliest_avg_object_bytes > 0
    AND latest_objects >= 100000
| EVAL object_growth_pct = ROUND((latest_objects - earliest_objects) / earliest_objects * 100.0, 2),
       byte_growth_pct   = ROUND((latest_bytes - earliest_bytes) / earliest_bytes * 100.0, 2),
       avg_object_size_change_pct = ROUND((latest_avg_object_bytes - earliest_avg_object_bytes) / earliest_avg_object_bytes * 100.0, 2)
// Divergence test: materially more objects, each materially smaller. Both clauses are needed —
// average size alone would fire on a bucket that merely deleted its largest objects.
// Loosen to -15 / 10 to catch sprawl earlier, tighten for buckets that churn by design.
| WHERE object_growth_pct > 20.0 AND avg_object_size_change_pct < -25.0
| SORT avg_object_size_change_pct ASC
| LIMIT 50
